import type { BrandHub } from './brandHub';
import type { KeywordFilters } from './keywordFilters';
import type { ProductSearchResult } from './productSearchResult';
import type { RetailerFilterNotice } from './retailerFilterNotice';

export interface SearchResponse {
  total: number;
  page: number;
  page_size: number;
  query: string;
  results: ProductSearchResult[];
  /** The retailers a stored preference narrowed this search to, or null when nothing was narrowed. Set only for browser callers carrying a `pp_uid` cookie, and only when the preference actually excludes a retailer — always null for API-key callers. */
  retailer_preference?: string[] | null;
  /** Set only when a `retailer` value could not be applied; null otherwise. Names what was dropped and which retailers the results actually come from. */
  retailer_filter?: RetailerFilterNotice | null;
  /** Words from `query` that match nothing on their own, so the results answer only the rest of the query. Empty when every word contributed. Only ever populated for multi-word queries that fell back to fuzzy matching — an exact-phase result requires the whole query, so it cannot have dropped a word. */
  unmatched_terms?: string[];
  /** True when no result contains every word of `query` and the results come from fuzzy matching, ranked by relevance. Re-sorting such results by price puts the loosest matches first. False when every result contains the whole query. */
  approximate?: boolean;
  /** Set when words in `q` name a filter rather than a product: `huismerk`/`huismerken` turn on `private_label=true`, `bio`/`biologisch` the dietary tag `bio`. Those words are removed from the search and the rest is searched with the filter added (`huismerk melk`). Null when no such word occurs. */
  keyword_filters?: KeywordFilters | null;
  /** The brand hub page answering this query, or null when the query does not name a brand that has one. Matched on the whole query, case- and punctuation-insensitively. */
  brand_hub?: BrandHub | null;
}
